INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (0, "やってやるですよ！", "50％でアルファルピ×2000\nさらに次のイベントへ", 0, 13161, 13161, 106601, "61_inori_guts");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (0, "もう一回挑戦だ！", "25％で★2迷宮遺物×1\nさらに次のイベントへ", 0, 23141, 23141, 105601, "52_ruka_fishing");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (1, "まだまだ\n食べ足りません☆", "50％で次のイベントへ", 0, 23151, 23151, 105801, "92_peko_guts");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (0, "それくらいで\nいいんじゃない？", "ランダムなロールの\nランダムサイン×2", 0, 23152, 23152, 106001, "92_kyaru_sad");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (1, "今日はツイてるです！", "50％でアルファルピ×4000\nさらに次のイベントへ", 2000, 23161, 23161, 106601, "62_inori_guts");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (0, "もうこの辺で……", "挑戦終了", 0, 23162, 23162, 105501, "62_ayumi_sad");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (0, "最後にもうひと勝負！", "10％で★3迷宮遺物×1", 0, 33141, 33141, 105601, "53_ruka_fishing");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (1, "えへへ～\nもうちょっとだけ……", "50％でオールセレクトサイン×２", 0, 33151, 33151, 105801, "93_peko_guts");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (0, "そんなに\n食べきれないでしょ！", "ランダムなロールの\nセレクトサイン×2", 0, 33152, 33152, 106001, "93_kyaru_anger");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (1, "今日のあたしは\n負け知らずです！", "50％でアルファルピ×8000", 4000, 33161, 33161, 106601, "63_inori_guts");
INSERT INTO `v1_5693ebd193831154c3cffc23c56fbab7770f4dee1962d83583975cf9d49f5810` VALUES (0, "そろそろやめた方が……", "挑戦終了", 0, 33162, 33162, 105501, "63_ayumi_worry");
